'use strict';
colors.Nova='#b9a3de';
bondDescriptions.Nova='Level 2: +1 moon crystal per pick';
creatureTemperaments.Nova={trait:'Distant · drawn to quiet','clues':['It hovers just out of reach, watching the sky.','It drifts a little lower, tracing slow circles above you.'],actions:[['still','Stand quietly'],['circle','Trace a slow circle'],['reach','Reach towards it']],best:['still','circle'],good:'It drifts down and settles nearby, wings glowing faintly.',bad:'It rises higher into the dark. Try something calmer.'};
const observatoryTypes=['observatoryMarker','observatoryNest'];
const observatoryNear=nearest;nearest=function(){let best=observatoryNear(),d=best?Math.hypot(best.x-player.x,best.y-player.y):43;for(const o of map.objects.filter(o=>observatoryTypes.includes(o.type))){const n=Math.hypot(o.x-player.x,o.y-player.y);if(n<d){best=o;d=n;}}return best;};
function observatoryChapter(){return ObservatoryCore.chapters[state.observatory.stage];}
function observatoryQuestCard(){const q=state.observatory,c=observatoryChapter();return `<article class="story-feature">${gameIcon(q.stage===6?'check':'crystals')}<small>STARLIGHT PLATEAU · ${Math.min(6,q.stage+1)} / 6</small><h3>${c?c[0]:'A dome open to the stars'}</h3><p>${c?c[1]:'Nova has a home, the dome turns freely and expeditions run a little further.'}</p>${q.stage===1?`<span>${q.markers.length} / 3 star-chart markers found</span>`:q.stage===2?`<span>${Math.min(12,Math.max(0,state.frontier.gathered.crystals-q.crystalStart))} / 12 fresh crystals</span>`:''}</article>`;}
function observatoryGuide(){panel('The observatory rekindles',observatoryQuestCard()+'<div class="actions"><button data-ui="close">Back to the trail</button><button data-front="requests">Regional requests</button></div>','Sage’s survey','observatory');}
function sageDialog(){const q=state.observatory;const lines=['“These old lenses have a story written in them. Will you help me read it again?”','“Three star-chart markers show where the old survey lines cross. Find them across the plateau.”','“Fresh crystals catch the light best. Gather twelve, then come find me.”','“Forty timber and twelve crystals should mend the dome. Meet me there.”','“Something drifts above the ridge at dusk. Follow the trail to the quiet skywatch.”','“You found our little stargazer! Let’s get this dome turning again.”','“Listen. The gears, the glass, the quiet. You’ve opened the whole plateau.”'];const action=q.stage===0?'talk':q.stage===2?'crystal':q.stage===5?'finish':null;panel('Sage',`<p>${lines[q.stage]}</p>${observatoryQuestCard()}<div class="actions">${action?`<button data-observatory="${action}" ${q.stage===2&&state.frontier.gathered.crystals-q.crystalStart<12?'disabled':''}>${q.stage===0?'I’ll help':q.stage===2?'Show the fresh crystals':'Celebrate · collect rewards'}</button>`:''}<button data-front="requests">Requests</button><button data-ui="close">See you soon</button></div>`,'Plateau astronomer','observatory');}
function observatoryObjectMenu(o){const q=state.observatory;let title='The plateau',body='',action='';
 if(o.type==='observatoryMarker'){title='A star-chart marker';body=q.markers.includes(o.marker)?'Already logged in Sage’s notes.':'A brass marker, angled towards the horizon. Worth reporting back.';if(q.stage===1&&!q.markers.includes(o.marker))action=`<button data-observatory="marker" data-marker="${o.marker}">Log this marker</button>`;}
 if(o.type==='landmark'){title='The old observatory dome';body=q.stage<3?'Sage has a plan for this place. Visit the camp to the south.':q.stage===3?'Repair the dome with fresh timber and crystals.':q.stage<6?'The gearing is sound. Follow Sage’s plan to bring the dome back.':'A working dome. Crystal gathering here now yields an extra piece.';if(q.stage===3)action=`${state.frontier.projects.observatory?'<p>Materials already paid for.</p>':`<div class="ingredient-row">${chip('wood',40,state.wood)}${chip('crystals',12,state.crystals)}</div>`}<button data-observatory="repair" ${!state.frontier.projects.observatory&&(state.wood<40||state.crystals<12)?'disabled':''}>Repair the dome</button>`;}
 if(o.type==='observatoryNest'){if(q.stage>=4&&!state.team.includes('Nova')){encounter={name:'Nova',trust:0};encounterDialog();return;}title='The quiet skywatch';body=state.team.includes('Nova')?'Nova drifts in a still hollow beneath the ridge. Always distant, always close by.':'Faint glimmers circle a quiet hollow. Perhaps a working dome will bring its owner out.';}
 panel(title,`<p>${body}</p>${action}<div class="actions"><button data-observatory="guide">Sage’s plan</button><button data-ui="close">Keep exploring</button></div>`,'Starlight Plateau','observatory');
}
const observatoryInteract=interact;interact=function(){if(!dialog&&!activity){const o=nearest();if(SaveStore.status().blocked){saveMenu();return;}if(map.id==='observatory'&&o?.name==='Sage'){sageDialog();return;}if(map.id==='observatory'&&(observatoryTypes.includes(o?.type)||o?.type==='landmark')){faceTarget(o);observatoryObjectMenu(o);return;}}observatoryInteract();};
app.addEventListener('click',e=>{const b=e.target.closest('[data-observatory]');if(!b||b.disabled)return;const a=b.dataset.observatory;if(a==='guide'){observatoryGuide();return;}if(SaveStore.status().blocked){saveMenu();return;}const o=nearest(),allowed=['talk','crystal','finish'].includes(a)?map.id==='observatory'&&o?.name==='Sage':map.id==='observatory'&&({marker:'observatoryMarker',repair:'landmark'}[a]===o?.type);if(!allowed||(a==='marker'&&Number(b.dataset.marker)!==o.marker))return;if(ObservatoryCore.act(state,a,Number(b.dataset.marker))){finish(a==='finish'?'The observatory rekindles! +100 coins · +3 trail marks · +6 crystals':a==='marker'?`${state.observatory.markers.length} / 3 markers found`:a==='repair'?'Dome repaired! Something still drifts above the ridge.':'Sage’s plan updated.');}if(o?.name==='Sage')sageDialog();else observatoryObjectMenu(o);});
const observatoryTick=tickActivities;tickActivities=function(dt){const people=map.npcs;if(map.id==='tessa')map.npcs=[];observatoryTick(dt);if(map.id==='tessa')map.npcs=people;if(ObservatoryCore.act(state,'friend')){state.jobs.Nova='crystals';finish('Nova joined the plateau camp. Tell Sage the good news!');}};
const observatoryComplete=completeActivity;completeActivity=function(){if(activity?.o.type==='crystals'&&state.life.active==='Nova'&&MossSystems.level(state,'Nova')>=2)state.crystals++;observatoryComplete();};
const observatoryAdventure=adventureMenu;adventureMenu=function(){observatoryAdventure();if(taskTab==='story'){const b=document.createElement('button');b.dataset.observatory='guide';b.textContent=state.observatory.stage===6?'Starlight Plateau · Complete':'Sage’s plateau · '+observatoryChapter()[0];document.querySelector('.dialog .panel-tabs').after(b);}};
const observatoryMap=mapPanel;mapPanel=function(){observatoryMap();const b=document.createElement('button');b.dataset.observatory='guide';b.textContent='Starlight Plateau · Sage’s plan';document.querySelector('.dialog').append(b);};
const observatoryObject=object;object=function(o){if(map.id==='observatory'){if(o.type==='observatoryMarker'){const found=state.observatory.markers.includes(o.marker);rr(o.x-3,o.y-14,6,14,'#6b6078');rr(o.x-7,o.y-17,14,6,found?'#c7b26a':'#8f7a4f');text(found?'✓':'?',o.x,o.y-12,found?'#eef3c0':'#f6e6ac',9);return;}if(o.type==='observatoryNest'){rr(o.x-13,o.y-3,26,7,'#5a5568');rr(o.x-9,o.y-6,18,5,'#9089a6');if(state.observatory.stage>=4&&!state.team.includes('Nova'))text('?',o.x,o.y-10,'#fff0b8',12);return;}}observatoryObject(o);};
// Old saves may stand where the new markers or nest now block a path.
if(map.id==='observatory'&&blocked(map,player.x,player.y)){player.x=23*T+16;player.y=35*T+16;follower.x=player.x-24;follower.y=player.y;save();}
